"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["579661"],{857871(e){e.exports=JSON.parse('{"tag":{"label":"tools","permalink":"/sdk/4.13.0/tags/tools","allTagsPath":"/sdk/4.13.0/tags","count":3,"items":[{"id":"guides/nowassist-skills-guide","title":"AI Skills Guide","description":"Create and configure AI Skills using the NowAssistSkillConfig API in the Fluent SDK. Skills use configured prompts to generate AI responses from an LLM, optionally enriched by inputs and tools (script, inline script, web search, subflows, flow actions, decision branches). This guide covers skill structure, inputs, prompts, deployment, and naming conventions. Requires SDK 4.6.0 or higher.","permalink":"/sdk/4.13.0/guides/nowassist-skills-guide"},{"id":"guides/building-ai-agents-tools-guide","title":"Building AI Agents \u2014 Tools Guide","description":"Configure and select tools for ServiceNow AI Agents and AI Agentic Workflows using the Fluent SDK. Covers tool types (CRUD, script, OOB, reference-based, RAG), tool discovery, execution mode, output transformation, and multi-tool composition patterns.","permalink":"/sdk/4.13.0/guides/building-ai-agents-tools-guide"},{"id":"guides/building-ai-agents-guide","title":"Building AI Agents Guide","description":"Build and configure ServiceNow AI Agents and AI Agentic Workflows using the Fluent SDK. AI Agents perform tasks with tools (CRUD, script, OOB, reference-based), while AI Agentic Workflows orchestrate multiple agents as a team. This guide covers agent structure, authentication, triggers, ACL deployment, and workflow configuration. Requires SDK 4.4.0 or higher.","permalink":"/sdk/4.13.0/guides/building-ai-agents-guide"}],"unlisted":false}}')}}]);